// scripts/gen-protocol-questions.mjs
//
// lib/protocolBook/{facial,nails}.ts -> lib/protocolBook/questions.ts
//
// The client forms (lib/formTemplates.ts) are loaded by the public /form page. Importing the protocol book there would ship
// every protocol, the full-book ones included, to anyone who opens a form link. So the forms read this small generated file
// instead: per protocol, only its key, field, tier, title and client questions, in the three languages.
// test-protocol-book.ts fails when this file and the book disagree, so a question edited in the book cannot silently
// leave the form behind. Re-run after editing a protocol's title or questions:
//
//   node --experimental-strip-types scripts/gen-protocol-questions.mjs

import fs from 'node:fs';
import { FACIAL } from '../lib/protocolBook/facial.ts';
import { NAILS } from '../lib/protocolBook/nails.ts';

const rows = [...FACIAL, ...NAILS].map((p) => ({
  key: p.key,
  formKey: `protocol_${p.key}`,
  field: p.field,
  tier: p.tier,
  title: { he: p.text.he.title, ar: p.text.ar.title, en: p.text.en.title },
  ask: { he: p.text.he.ask, ar: p.text.ar.ask, en: p.text.en.ask },
}));

const out = `// lib/protocolBook/questions.ts
//
// GENERATED by scripts/gen-protocol-questions.mjs from the protocol book. Do not hand-edit: edit the protocol, re-run the script.
// Only what a client form needs (lib/formTemplates.ts): never the protocol itself, which stays out of the public /form bundle.
//
// APPEND-ONLY per protocol: a signed form stores answers by question index, so a question is added at the END of a protocol's
// "ask" list, never inserted or removed (test-protocol-book.ts keeps a frozen copy of the first lists).

export type ProtocolForm = {
  key: string;
  formKey: string;
  field: 'cosmetics' | 'nails';
  tier: 'free' | 'full';
  title: { he: string; ar: string; en: string };
  ask: { he: string[]; ar: string[]; en: string[] };
};

export const PROTOCOL_FORMS: ProtocolForm[] = ${JSON.stringify(rows, null, 2)};

export const PROTOCOL_FORM_PREFIX = 'protocol_';
export const protocolFormOf = (formKey: unknown): ProtocolForm | undefined =>
  typeof formKey === 'string' ? PROTOCOL_FORMS.find((f) => f.formKey === formKey) : undefined;

/** The form's title in a language: "שאלון לפני טיפול: אקנה". */
export const PROTOCOL_FORM_TITLE = { he: 'שאלון לפני טיפול', ar: 'استبيان قبل العلاج', en: 'Before your treatment' } as const;
export const protocolFormTitle = (f: ProtocolForm, lang: 'he' | 'ar' | 'en'): string => \`\${PROTOCOL_FORM_TITLE[lang]}: \${f.title[lang]}\`;
`;

fs.writeFileSync(new URL('../lib/protocolBook/questions.ts', import.meta.url), out);
console.log(`wrote ${rows.length} protocol forms`);
